<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Learning Center — EngineerLaunch</title><style>:root{--blue:#1769ff;--ink:#17233c;--muted:#697890;--line:#e1e7f0}*{box-sizing:border-box}body{margin:0;background:#f8fbff;color:var(--ink);font-family:Inter,system-ui}a{text-decoration:none;color:inherit}.wrap{width:min(1120px,calc(100% - 32px));margin:auto}.hero{padding:50px 0 28px;background:radial-gradient(circle at 76% 38%,#dfe9ff,transparent 28%),linear-gradient(130deg,#f0fbff,#fff 55%,#f6f1ff)}.hero-grid{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:40px}.badge{display:inline-block;padding:7px 12px;border-radius:999px;background:#e7eeff;color:var(--blue);font-size:12px;font-weight:800}.hero h1{margin:14px 0;font-size:clamp(40px,5vw,61px);line-height:1.03;letter-spacing:-2px}.hero h1 span{color:#7657f6}.hero p{max-width:570px;color:var(--muted);line-height:1.7}.benefits{display:flex;gap:20px;flex-wrap:wrap;margin-top:22px;font-size:13px;font-weight:700}.visual{position:relative;min-height:260px;display:grid;place-items:center}.window{width:75%;padding:22px;border-radius:18px;background:#fff;box-shadow:0 25px 60px #5369a525;transform:rotate(2deg)}.line{height:11px;margin:13px 0;border-radius:7px;background:#e8edf7}.line:first-child{width:55%;background:#cdd9ff}.line:nth-child(3){width:72%}.float{position:absolute;display:grid;place-items:center;width:57px;height:57px;border-radius:14px;color:#fff;font-weight:900;box-shadow:0 12px 25px #5369a52a}.one{left:8%;top:18%;background:#4778ef}.two{right:7%;top:38%;background:#7c3aed}.three{left:17%;bottom:10%;background:#0aa483}.paths{padding:30px 0 60px}.title-row{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.title-row h2{margin:0;font-size:28px}.practice{padding:10px 14px;border-radius:8px;background:#eaf1ff;color:var(--blue);font-size:13px;font-weight:800}.grid{display:grid;grid-template-